import { fetchReceiptPdf } from '../../services/api';

// Receipts are generated by the server from the persisted payment; the browser only shows,
// saves or prints the PDF it receives (with the signed-in user's token).

const REVOKE_AFTER_MS = 60_000;
const releaseLater = (url) => setTimeout(() => URL.revokeObjectURL(url), REVOKE_AFTER_MS);

/** Opens the receipt in a new tab. The tab is opened first, synchronously, to avoid popup blocking. */
export async function viewReceipt(transactionId) {
  const tab = window.open('', '_blank');
  try {
    const url = URL.createObjectURL(await fetchReceiptPdf(transactionId));
    if (tab) {
      tab.opener = null;
      tab.location.href = url;
    } else {
      window.location.href = url;
    }
    releaseLater(url);
  } catch (error) {
    tab?.close();
    throw error;
  }
}

/** Saves the receipt as DAC-Payment-Receipt-<id>.pdf. */
export async function downloadReceipt(transactionId) {
  const url = URL.createObjectURL(await fetchReceiptPdf(transactionId, { download: true }));
  const link = document.createElement('a');
  link.href = url;
  link.download = `DAC-Payment-Receipt-${transactionId}.pdf`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  releaseLater(url);
}

/** Prints the receipt through a hidden frame, using the browser's PDF viewer. */
export async function printReceipt(transactionId) {
  const url = URL.createObjectURL(await fetchReceiptPdf(transactionId));
  const frame = document.createElement('iframe');
  frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden';
  frame.title = 'Receipt print frame';
  frame.src = url;
  frame.onload = () => {
    try {
      frame.contentWindow?.focus();
      frame.contentWindow?.print();
    } catch {
      window.open(url, '_blank', 'noopener'); // Fallback: open it so the user can print.
    }
  };
  document.body.appendChild(frame);
  setTimeout(() => {
    frame.remove();
    URL.revokeObjectURL(url);
  }, REVOKE_AFTER_MS);
}
